using System.Collections.Immutable;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace Generator;

[Generator]
public class NameEnumGenerator : IIncrementalGenerator
{
    private const string AttributeText = @"
// <auto-generated/>
using System;

[AttributeUsage(AttributeTargets.Enum, AllowMultiple = false, Inherited = false)]
internal sealed class NameEnumAttribute : Attribute
{
    public NameEnumAttribute() { }
}
";

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        // 生成特性代码
        context.RegisterPostInitializationOutput(ctx =>
            ctx.AddSource("NameEnumAttribute.g.cs", SourceText.From(AttributeText, Encoding.UTF8)));

        // 收集所有带有 [NameEnum] 的枚举
        var enumDeclarations = context.SyntaxProvider
            .CreateSyntaxProvider(
                predicate: static (node, _) => node is EnumDeclarationSyntax,
                transform: static (ctx, _) => GetEnumInfo(ctx))
            .Where(static info => info is not null)
            .Select(static (info, _) => info!.Value)
            .Collect();

        // 生成静态类
        context.RegisterSourceOutput(enumDeclarations, (spc, enums) => GenerateNamesClasses(spc, enums));
    }

    private static (string Namespace, string EnumName, ImmutableArray<string> MemberNames)? GetEnumInfo(GeneratorSyntaxContext context)
    {
        var enumDecl = (EnumDeclarationSyntax)context.Node;
        var model = context.SemanticModel;
        var enumSymbol = model.GetDeclaredSymbol(enumDecl) as INamedTypeSymbol;
        if (enumSymbol == null) return null;

        // 检查是否应用了 [NameEnum] 特性
        bool hasAttribute = false;
        foreach (var attr in enumSymbol.GetAttributes())
        {
            if (attr.AttributeClass?.Name == "NameEnumAttribute")
            {
                hasAttribute = true;
                break;
            }
        }
        if (!hasAttribute) return null;

        // 获取枚举成员名称（不包括特殊字段 __value）
        var memberNames = ImmutableArray.CreateBuilder<string>();
        foreach (var member in enumSymbol.GetMembers())
        {
            if (member is IFieldSymbol field && field.ConstantValue != null)
            {
                memberNames.Add(member.Name);
            }
        }

        // 确定命名空间（如果枚举在全局命名空间，则为 null）
        string ns = enumSymbol.ContainingNamespace.IsGlobalNamespace
            ? null
            : enumSymbol.ContainingNamespace.ToString();

        return (ns, enumSymbol.Name, memberNames.ToImmutable());
    }

    private static void GenerateNamesClasses(SourceProductionContext spc, ImmutableArray<(string Namespace, string EnumName, ImmutableArray<string> MemberNames)> enums)
    {
        if (enums.IsDefaultOrEmpty) return;

        foreach (var (ns, enumName, memberNames) in enums)
        {
            // 生成类名：去掉末尾的 "Enum" 并加 "s"，或者直接加 "Names"
            // 示例：UnitNameEnum -> UnitNames
            string className = enumName.EndsWith("Enum")
                ? enumName.Substring(0, enumName.Length - 4) + "s"
                : enumName + "Names";

            var sb = new StringBuilder();
            sb.AppendLine("// <auto-generated/>");
            sb.AppendLine("#nullable enable");
            sb.AppendLine();

            if (!string.IsNullOrEmpty(ns))
            {
                sb.AppendLine($"namespace {ns}");
                sb.AppendLine("{");
                sb.AppendLine($"    public static class {className}");
                sb.AppendLine("    {");
                foreach (var member in memberNames)
                {
                    sb.AppendLine($"        public static readonly string {member} = \"{member}\";");
                }
                sb.AppendLine("    }");
                sb.AppendLine("}");
            }
            else
            {
                // 全局命名空间下，直接定义类
                sb.AppendLine($"public static class {className}");
                sb.AppendLine("{");
                foreach (var member in memberNames)
                {
                    sb.AppendLine($"    public static readonly string {member} = \"{member}\";");
                }
                sb.AppendLine("}");
            }

            spc.AddSource($"{className}.g.cs", SourceText.From(sb.ToString(), Encoding.UTF8));
        }
    }
}